<?php require __DIR__.'/includes/layout.php';$rows=[];try{$rows=db()->query('SELECT * FROM csNews ORDER BY NewsDate DESC,ID DESC')->fetchAll();}catch(Throwable){}admin_header('Новости');?><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Дата</th><th>Заголовок</th><th>Статус</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=aesc((string)($r['NewsDate']??''))?></td><td><?=aesc(a_legacy($r['Title']??''))?></td><td><span class="badge <?=!empty($r['IsPublish'])?'on':'off'?>"><?=!empty($r['IsPublish'])?'Опубликована':'Скрыта'?></span></td></tr><?php endforeach;?></tbody></table></div></div><?php admin_footer();
